src/cards/counter/counter.card.ts<pre><code>import {
  createCardDeclaration,
  createOnAction,
  registerActions,
  registerMetaCard,
} from "@pihanga2/core";
import type {
  PiCardDef,
  PiMapProps,
  PiRegisterMetaCard,
  ReduxState,
  RegisterCardF,
} from "@pihanga2/core";
import {Stack, Button, Typography} from "@pihanga2/shadcn";

const COUNTER_CARD = "meta/counter";

/** Card declaration — drop a Counter anywhere in a layout: */
export const Counter = createCardDeclaration&lt;CounterProps, CounterEvents&gt;(
  COUNTER_CARD,
);

/** Namespaced action constants for the Counter meta card. */
export const COUNTER_ACTION = registerActions(COUNTER_CARD, ["changed"]);

/**
 * Convenience helper for reducers that respond to a counter change.
 *
 * @example
 * ```ts
 * onCounterChanged(register, (state, { value }) =&gt; { state.count = value });
 * ```
 */
export const onCounterChanged = createOnAction&lt;CounterChangeEvent&gt;(
  COUNTER_ACTION.CHANGED,
);

type CounterProps  = { value: number };
type CounterEvents = { onChange: CounterChangeEvent };
export type CounterChangeEvent = { value: number };
</code></pre>

src/app.pihanga.ts<pre><code>import {registerCard} from "@pihanga2/core";
import type {AppState} from "./app.state";
// Importing registers the "meta/counter" type automatically
import {Counter, onCounterChanged} from "./cards/counter/counter.card";

registerCard(
  "page/counter",
  Counter&lt;AppState&gt;({
    value: (s) =&gt; s.count,                      // state mapper
    onChange: (state, {value}) =&gt; {
      state.count = value;
    },
  }),
);
</code></pre> <p>When flushed, <code>_registerCard</code> finds <code>"meta/counter"</code> in <code>metacardTypes</code> and calls <code>CounterMapper</code>, which registers:</p> <ul> <li><code>"page/counter/plus"</code> → <code>shadcn/button</code></li> <li><code>"page/counter"</code> → <code>shadcn/stack</code> (the top card, containing inline sub-cards)</li> </ul>

src/app.reducer.ts<pre><code>import { type PiRegister } from "@pihanga2/core";
import type { AppState } from "./app.types";

export function reducerInit(register: PiRegister): void {
  register.reducer.register&lt;AppState&gt;(
    "COUNTER/INCREMENT",
    (state, action) =&gt; {
      state.count += action.delta;
      return state;
    },
  );
}
</code></pre>

items.reducer.ts<pre><code>import { createOnAction } from "@pihanga2/core"
import type { AppState } from "./app.state"

export const onItemLoaded = createOnAction&lt;{ item: Item }&gt;("ITEM/LOADED")

export function init(register: any) {
  onItemLoaded&lt;AppState&gt;(register, (state, { item }) =&gt; {
    state.items = [...(state.items ?? []), item]
    return state
  })
}
</code></pre> items.reducer.test.ts<pre><code>import { describe, it, expect } from "vitest"

// Import the raw reducer handler — no framework required
function itemLoadedReducer(state: any, { item }: any) {
  state.items = [...(state.items ?? []), item]
  return state
}

describe("itemLoadedReducer", () =&gt; {
  it("appends the item to state.items", () =&gt; {
    const state = { items: [{ id: "1" }] }
    const result = itemLoadedReducer(structuredClone(state), { item: { id: "2" } })
    expect(result.items).toHaveLength(2)
    expect(result.items[1]).toEqual({ id: "2" })
  })

  it("initialises items array when undefined", () =&gt; {
    const result = itemLoadedReducer({}, { item: { id: "new" } })
    expect(result.items).toEqual([{ id: "new" }])
  })
})
</code></pre>
